add_action( 'wpo_wcpdf_after_order_details', 'perfectpixel_customer_notes_on_pdf_invoice', 10, 2 );

function perfectpixel_customer_notes_on_pdf_invoice( $document_type, $order ) {
	if ( 'invoice' !== $document_type || ! $order instanceof WC_Order ) {
		return;
	}
	$notes = $order->get_customer_order_notes();
	if ( ! $notes ) {
		return;
	}
	echo '<div class="perfectpixel-pdf-notes"><h3>' . esc_html( '{{pdf_notes_heading}}' ) . '</h3>';
	foreach ( $notes as $note ) {
		echo '<p>' . wp_kses_post( wpautop( wptexturize( $note->comment_content ) ) ) . '</p>';
	}
	echo '</div>';
}
